var f1 = function(x){ return Math.pow(1/3, 2*x-1); };
var f2 = function(x){ return Math.pow(27, x-2); };
board.create('functiongraph', [f1, -1, 4], {strokeColor: '#3b82f6', strokeWidth: 3, name: 'y=(1/3)^(2x-1)'});
board.create('functiongraph', [f2, -1, 4], {strokeColor: '#ef4444', strokeWidth: 3, name: 'y=27^(x-2)'});
var p = board.create('point', [1.4, Math.pow(27, -0.6)], {name: 'Intersection (1.4, 0.14)', size: 4, fillColor: '#10b981', strokeColor: '#10b981', label: {offset: [10, 10]}});

board.create('text', [2, 5, 'Intersection reveals the root x = 7/5 = 1.4'], {fontSize: 14});
